"use strict";(self.webpackChunkdoc_adk_training_site=self.webpackChunkdoc_adk_training_site||[]).push([[9438],{5444:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>a,default:()=>u,frontMatter:()=>i,metadata:()=>s,toc:()=>c});const s=JSON.parse('{"id":"module22-state-and-memory/lab-solution","title":"Lab Solution","description":"Goal","source":"@site/../training/module22-state-and-memory/lab-solution.md","sourceDirName":"module22-state-and-memory","slug":"/module22-state-and-memory/lab-solution","permalink":"/doc-adk-training/docs/module22-state-and-memory/lab-solution","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":3,"frontMatter":{"sidebar_position":3,"title":"Lab Solution"}}');var r=t(4848),o=t(8453);const i={sidebar_position:3,title:"Lab Solution"},a="Lab 22 Solution: Building a Personal Learning Tutor",l={},c=[{value:"Goal",id:"goal",level:2},{value:"<code>personal_tutor/agent.py</code>",id:"personal_tutoragentpy",level:3},{value:"Self-Reflection Answers",id:"self-reflection-answers",level:3}];function d(e){const n={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",ol:"ol",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"lab-22-solution-building-a-personal-learning-tutor",children:"Lab 22 Solution: Building a Personal Learning Tutor"})}),"\n",(0,r.jsx)(n.h2,{id:"goal",children:"Goal"}),"\n",(0,r.jsxs)(n.p,{children:["This file contains the complete code for the ",(0,r.jsx)(n.code,{children:"agent.py"})," script in the Personal Learning Tutor lab."]}),"\n",(0,r.jsx)(n.h3,{id:"personal_tutoragentpy",children:(0,r.jsx)(n.code,{children:"personal_tutor/agent.py"})}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-python",children:"\"\"\"\nPersonal Learning Tutor - Demonstrates State & Memory Management\n\nThis agent uses:\n- user: prefix for persistent preferences (language, difficulty)\n- Session state for current topic tracking\n- temp: prefix for temporary quiz calculations\n- Memory service for retrieving past learning sessions\n\"\"\"\n\nfrom google.adk.agents import Agent\nfrom google.adk.tools.tool_context import ToolContext\nfrom typing import Dict, Any\n\n# ============================================================================\n# TOOLS: State Management & Memory Operations\n# ============================================================================\n\ndef set_user_preferences(\n    language: str,\n    difficulty_level: str,\n    tool_context: ToolContext\n) -> Dict[str, Any]:\n    \"\"\"\n    Set user learning preferences (stored persistently).\n\n    Args:\n        language: Preferred language (en, es, fr, etc.)\n        difficulty_level: beginner, intermediate, or advanced\n    \"\"\"\n    # Use user: prefix for persistent cross-session storage\n    tool_context.state['user:language'] = language\n    tool_context.state['user:difficulty_level'] = difficulty_level\n\n    return {\n        'status': 'success',\n        'message': f'Preferences saved: {language}, {difficulty_level} level'\n    }\n\n\ndef record_topic_completion(\n    topic: str,\n    quiz_score: int,\n    tool_context: ToolContext\n) -> Dict[str, Any]:\n    \"\"\"\n    Record that user completed a topic (stored persistently).\n\n    Args:\n        topic: Topic name (e.g., \"Python Basics\", \"Data Structures\")\n        quiz_score: Score out of 100\n    \"\"\"\n    # Get existing lists or create new ones\n    topics = tool_context.state.get('user:topics_covered', [])\n    scores = tool_context.state.get('user:quiz_scores', {})\n\n    # Update persistent user state\n    if topic not in topics:\n        topics.append(topic)\n    scores[topic] = quiz_score\n\n    tool_context.state['user:topics_covered'] = topics\n    tool_context.state['user:quiz_scores'] = scores\n\n    return {\n        'status': 'success',\n        'topics_count': len(topics),\n        'message': f'Recorded: {topic} with score {quiz_score}/100'\n    }\n\n\ndef get_user_progress(tool_context: ToolContext) -> Dict[str, Any]:\n    \"\"\"\n    Get user's learning progress summary.\n\n    Returns persistent user data across all sessions.\n    \"\"\"\n    # Read persistent user state\n    language = tool_context.state.get('user:language', 'en')\n    difficulty = tool_context.state.get('user:difficulty_level', 'beginner')\n    topics = tool_context.state.get('user:topics_covered', [])\n    scores = tool_context.state.get('user:quiz_scores', {})\n\n    # Calculate average score\n    avg_score = sum(scores.values()) / len(scores) if scores else 0\n\n    return {\n        'status': 'success',\n        'language': language,\n        'difficulty_level': difficulty,\n        'topics_completed': len(topics),\n        'topics': topics,\n        'average_quiz_score': round(avg_score, 1),\n        'all_scores': scores\n    }\n\n\ndef start_learning_session(\n    topic: str,\n    tool_context: ToolContext\n) -> Dict[str, Any]:\n    \"\"\"\n    Start a new learning session for a topic.\n\n    Uses session state (no prefix) to track current topic.\n    \"\"\"\n    # Session-level state (persists within this session only)\n    tool_context.state['current_topic'] = topic\n    tool_context.state['session_start_time'] = 'now'  # Simplified\n\n    # Get user's difficulty level for personalization\n    difficulty = tool_context.state.get('user:difficulty_level', 'beginner')\n\n    return {\n        'status': 'success',\n        'topic': topic,\n        'difficulty_level': difficulty,\n        'message': f'Started learning session: {topic} at {difficulty} level'\n    }\n\n\ndef calculate_quiz_grade(\n    correct_answers: int,\n    total_questions: int,\n    tool_context: ToolContext\n) -> Dict[str, Any]:\n    \"\"\"\n    Calculate quiz grade using temporary state.\n\n    Demonstrates temp: prefix for invocation-scoped data.\n    \"\"\"\n    # Store intermediate calculation in temp state (discarded after invocation)\n    percentage = (correct_answers / total_questions) * 100\n    tool_context.state['temp:raw_score'] = correct_answers\n    tool_context.state['temp:quiz_percentage'] = percentage\n\n    # Determine grade letter\n    if percentage >= 90:\n        grade = 'A'\n    elif percentage >= 80:\n        grade = 'B'\n    elif percentage >= 70:\n        grade = 'C'\n    elif percentage >= 60:\n        grade = 'D'\n    else:\n        grade = 'F'\n\n    return {\n        'status': 'success',\n        'score': f'{correct_answers}/{total_questions}',\n        'percentage': round(percentage, 1),\n        'grade': grade,\n        'message': f'Quiz grade: {grade} ({percentage:.1f}%)'\n    }\n\n\ndef search_past_lessons(\n    query: str,\n    tool_context: ToolContext\n) -> Dict[str, Any]:\n    \"\"\"\n    Search memory for relevant past learning sessions.\n\n    This demonstrates memory service integration.\n    In production, this would use MemoryService.search_memory().\n    \"\"\"\n    # NOTE: This is a simplified simulation\n    topics = tool_context.state.get('user:topics_covered', [])\n    relevant = [t for t in topics if query.lower() in t.lower()]\n\n    if relevant:\n        return {\n            'status': 'success',\n            'found': True,\n            'relevant_topics': relevant,\n            'message': f'Found {len(relevant)} past sessions related to \"{query}\"'\n        }\n    else:\n        return {\n            'status': 'success',\n            'found': False,\n            'message': f'No past sessions found for \"{query}\"'\n        }\n\n\n# ============================================================================\n# AGENT DEFINITION\n# ============================================================================\n\nroot_agent = Agent(\n    name=\"personal_tutor\",\n    model=\"gemini-3.5-flash\",\n    description=\"Personal learning tutor that tracks your progress, preferences, and learning history.\",\n    instruction=\"\"\"\n    You are a personalized learning tutor (Course Version {app:course_version?}) with memory of the user's progress.\n\n    CAPABILITIES:\n    - Set and remember user preferences (language, difficulty level)\n    - Track completed topics and quiz scores across sessions\n    - Start new learning sessions on specific topics\n    - Calculate quiz grades and store results\n    - Search past learning sessions for context\n    - Adapt teaching based on user's level and history\n\n    WORKFLOW:\n    1. If new user, ask about preferences (language, difficulty).\n    2. For learning requests, start a session with start_learning_session and teach the topic.\n    3. After teaching, record completion with the user's quiz score.\n    4. When asked, search past lessons to provide context.\n\n    Always be encouraging and adapt to the user's learning pace!\n    \"\"\",\n    tools=[\n        set_user_preferences,\n        record_topic_completion,\n        get_user_progress,\n        start_learning_session,\n        calculate_quiz_grade,\n        search_past_lessons\n    ],\n    output_key=\"last_tutor_response\"\n)\n"})}),"\n",(0,r.jsx)(n.h3,{id:"self-reflection-answers",children:"Self-Reflection Answers"}),"\n",(0,r.jsxs)(n.ol,{children:["\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:(0,r.jsxs)(n.strong,{children:["The ",(0,r.jsx)(n.code,{children:"InMemorySessionService"})," loses ",(0,r.jsx)(n.code,{children:"user:"})," and ",(0,r.jsx)(n.code,{children:"app:"})," state on restart. What are the advantages and disadvantages of using a persistent ",(0,r.jsx)(n.code,{children:"SessionService"})," (like one backed by a database) in a production environment?"]})}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Answer:"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Advantages:"})," True persistence across restarts/deployments; enables long-term personalization; supports horizontal scaling (multiple instances of your agent can access the same state); critical for user-facing applications that need to remember users."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Disadvantages:"})," Adds operational overhead (database management, network latency); requires careful schema design; potential for data consistency issues in distributed systems if not managed well."]}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:(0,r.jsxs)(n.strong,{children:["The ",(0,r.jsx)(n.code,{children:"temp:"})," state is automatically discarded after each turn. Why is this a useful feature? What kind of problems could arise if this temporary data was accidentally persisted?"]})}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Answer:"})," ",(0,r.jsx)(n.code,{children:"temp:"})," state is useful for intermediate calculations or ephemeral data that is only relevant for a single turn (e.g., a quiz score before it's saved to ",(0,r.jsx)(n.code,{children:"user:"})," state). If this data was accidentally persisted:","\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"State Bloat:"})," The state object would grow unnecessarily large over time, slowing down processing."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Data Pollution:"})," Irrelevant data would clutter the state, potentially confusing the LLM in later turns or leading to incorrect decisions."]}),"\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Security Risks:"})," Sensitive temporary data might be unintentionally exposed or stored longer than intended."]}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,r.jsxs)(n.li,{children:["\n",(0,r.jsx)(n.p,{children:(0,r.jsxs)(n.strong,{children:["Our ",(0,r.jsx)(n.code,{children:"search_past_lessons"})," tool simulates a memory search. In a real application using ",(0,r.jsx)(n.code,{children:"VertexAiMemoryBankService"}),", the search would be semantic (based on meaning) rather than keyword-based. How does this change the kinds of queries the user could make?"]})}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsxs)(n.li,{children:[(0,r.jsx)(n.strong,{children:"Answer:"})," Semantic search is much more powerful. Instead of needing to remember exact keywords or topic titles, a user could ask conceptual questions like:","\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"\"What did we discuss about data transformation last week?\" (Even if the topic was 'ETL processes')."}),"\n",(0,r.jsx)(n.li,{children:"\"Remind me about the security implications of that code review we did.\" (Even if the exact phrase 'security implications' wasn't used)."}),"\n",(0,r.jsx)(n.li,{children:"\"I'm confused about asynchronous programming; what did you teach me about Python coroutines?\"\nThis allows for a more natural, intuitive, and flexible interaction with the agent's long-term knowledge."}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n"]})]})}function u(e={}){const{wrapper:n}={...(0,o.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(d,{...e})}):d(e)}},8453:(e,n,t)=>{t.d(n,{R:()=>i,x:()=>a});var s=t(6540);const r={},o=s.createContext(r);function i(e){const n=s.useContext(o);return s.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function a(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:i(e.components),s.createElement(o.Provider,{value:n},e.children)}}}]);